ALTER TABLE `customers` ADD COLUMN `password_hash` VARCHAR(255) NULL AFTER `accepts_communications`;

CREATE TABLE `customer_sessions` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`customer_id` BIGINT UNSIGNED NOT NULL,`token_hash` CHAR(64) NOT NULL,`expires_at` DATETIME(3) NOT NULL,`last_seen_at` DATETIME(3) NOT NULL,`revoked_at` DATETIME(3) NULL,`revocation_reason` VARCHAR(100) NULL,`ip_address` VARCHAR(45) NULL,`user_agent` VARCHAR(255) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `customer_sessions_public_id_key` (`public_id`),UNIQUE INDEX `customer_sessions_token_hash_key` (`token_hash`),INDEX `customer_sessions_customer_id_revoked_at_expires_at_idx` (`customer_id`,`revoked_at`,`expires_at`),INDEX `customer_sessions_tenant_id_customer_id_idx` (`tenant_id`,`customer_id`),CONSTRAINT `customer_sessions_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `customer_sessions_customer_id_fkey` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
